  "CREATE TRIGGER feed_generation_users_insert AFTER INSERT ON users BEGIN\n        UPDATE feed_snapshot_generation SET generation=generation+1 WHERE id=1; END;",
  "CREATE TRIGGER feed_generation_users_update AFTER UPDATE ON users BEGIN\n        UPDATE feed_snapshot_generation SET generation=generation+1 WHERE id=1; END;",
